content.text:
Brief:
Un labyrinthe de haies vu du dessus, joué au tour par tour. Le joueur guide un hérisson case par case en glissant le doigt vers une direction. Chaque déplacement coûte un pas, et des pommes posées dans les allées rapportent des points. La partie est gagnée quand le hérisson atteint la sortie, et elle est bloquée si plus aucun pas ne reste. Aucun chronomètre ne presse le joueur.

Plan:
{"gameType":"puzzle-board","input":"swipe-lanes","lang":"fr","loop":"Glissez le doigt pour guider le hérisson case par case dans le labyrinthe de haies et ramasser des pommes. Chaque pas compte : atteignez la sortie avant d'être à court de pas, sinon la partie est bloquée.","slug":"le-herisson-des-haies","style":"paper-cut","title":"Le Hérisson des Haies"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Hérisson des Haies</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     touch-action: none;
13|     font-family: "Segoe UI", Verdana, Arial, sans-serif;
14|   }
15|   #wrap {
16|     position: fixed; inset: 0;
17|     display: flex; align-items: center; justify-content: center;
18|   }
19|   canvas {
20|     display: block;
21|     touch-action: none;
22|   }
23|   #hint {
24|     position: absolute;
25|     bottom: 8px; left: 0; right: 0;
26|     text-align: center;
27|     color: #3d405b;
28|     font-size: 14px;
29|     pointer-events: none;
30|     user-select: none;
31|   }
32| </style>
33| </head>
34| <body>
35| <div id="wrap">
36|   <canvas id="game"></canvas>
37| </div>
38| <div id="hint">Glissez pour déplacer le hérisson (haut / bas / gauche / droite)</div>
39| <script>
40|   const CARTRIDGE = {
41|     send(type, payload = {}) {
42|       window.parent.postMessage(
43|         { source: "cartridge", v: 1, type, payload },
44|         "*",
45|       );
46|     },
47|   };
48| </script>
49| <script>
50| (function(){
51|   const canvas = document.getElementById('game');
52|   const ctx = canvas.getContext('2d');
53|   const hint = document.getElementById('hint');
54| 
55|   const COLORS = {
56|     bg: '#f4ecd8',
57|     layer: '#e07a5f',
58|     accent: '#3d405b',
59|     highlight: '#81b29a'
60|   };
61| 
62|   // ---------- seeded jitter ----------
63|   let seedState = 12345;
64|   function seededRandom() {
65|     seedState = (seedState * 1103515245 + 12345) & 0x7fffffff;
66|     return (seedState % 10000) / 10000;
67|   }
68|   const jitterCache = new Map();
69|   function jitter(key, amp) {
70|     if (jitterCache.has(key)) return jitterCache.get(key);
71|     const v = (seededRandom() - 0.5) * 2 * amp;
72|     jitterCache.set(key, v);
73|     return v;
74|   }
75| 
76|   function jitteredPolygon(ctx, pts, keyPrefix, amp) {
77|     ctx.beginPath();
78|     pts.forEach((p, i) => {
79|       const jx = jitter(keyPrefix + 'x' + i, amp);
80|       const jy = jitter(keyPrefix + 'y' + i, amp);
81|       const x = p[0] + jx, y = p[1] + jy;
82|       if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
83|     });
84|     ctx.closePath();
85|   }
86| 
87|   function roundRectPath(ctx, x, y, w, h, r) {
88|     ctx.beginPath();
89|     ctx.moveTo(x + r, y);
90|     ctx.arcTo(x + w, y, x + w, y + h, r);
91|     ctx.arcTo(x + w, y + h, x, y + h, r);
92|     ctx.arcTo(x, y + h, x, y, r);
93|     ctx.arcTo(x, y, x + w, y, r);
94|     ctx.closePath();
95|   }
96| 
97|   // ---------- layout ----------
98|   let W = 0, H = 0, DPR = 1;
99|   function resize() {
100|     DPR = window.devicePixelRatio || 1;
101|     W = window.innerWidth;
102|     H = window.innerHeight;
103|     canvas.width = Math.floor(W * DPR);
104|     canvas.height = Math.floor(H * DPR);
105|     canvas.style.width = W + 'px';
106|     canvas.style.height = H + 'px';
107|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
108|     draw();
109|   }
110|   window.addEventListener('resize', resize);
111| 
112|   // ---------- game state ----------
113|   const GRID = 7; // 7x7 maze
114|   let stage = 1;
115|   let paused = false;
116|   let started = false;
117|   let gameOver = false;
118|   let endReason = null;
119| 
120|   let grid = []; // 0 empty, 1 hedge, 2 apple, 3 exit
121|   let hx = 0, hy = 0; // hedgehog position
122|   let stepsLeft = 0;
123|   let score = 0;
124|   let applesTotal = 0;
125| 
126|   function inBounds(x, y) {
127|     return x >= 0 && x < GRID && y >= 0 && y < GRID;
128|   }
129| 
130|   function genMaze(seedBase) {
131|     seedState = seedBase;
132|     jitterCache.clear();
133|     grid = [];
134|     for (let y = 0; y < GRID; y++) {
135|       const row = [];
136|       for (let x = 0; x < GRID; x++) row.push(1);
137|       grid.push(row);
138|     }
139|     // carve a maze using randomized DFS on odd coordinates conceptually,
140|     // but simpler: carve on full grid with backtracking, allow all cells as nodes
141|     function shuffle(arr) {
142|       for (let i = arr.length - 1; i > 0; i--) {
143|         const j = Math.floor(seededRandom() * (i + 1));
144|         const t = arr[i]; arr[i] = arr[j]; arr[j] = t;
145|       }
146|       return arr;
147|     }
148|     const stack = [[0,0]];
149|     const visited = new Set(['0,0']);
150|     grid[0][0] = 0;
151|     while (stack.length) {
152|       const [cx, cy] = stack[stack.length - 1];
153|       const dirs = shuffle([[1,0],[-1,0],[0,1],[0,-1]]);
154|       let moved = false;
155|       for (const [dx, dy] of dirs) {
156|         const nx = cx + dx, ny = cy + dy;
157|         if (inBounds(nx, ny) && !visited.has(nx+','+ny)) {
158|           visited.add(nx+','+ny);
159|           grid[ny][nx] = 0;
160|           stack.push([nx, ny]);
161|           moved = true;
162|           break;
163|         }
164|       }
165|       if (!moved) stack.pop();
166|     }
167|     // knock a few extra walls down for loop options (keep it a puzzle, moderate)
168|     let extra = Math.floor(GRID * 1.2);
169|     while (extra > 0) {
170|       const x = Math.floor(seededRandom() * GRID);
171|       const y = Math.floor(seededRandom() * GRID);
172|       if (grid[y][x] === 1) {
173|         // only open if it connects two open cells (avoid isolated hedges disappearing randomly on edges)
174|         let openNeighbors = 0;
175|         [[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy]) => {
176|           const nx = x+dx, ny = y+dy;
177|           if (inBounds(nx,ny) && grid[ny][nx] === 0) openNeighbors++;
178|         });
179|         if (openNeighbors >= 2) {
180|           grid[y][x] = 0;
181|           extra--;
182|         } else {
183|           extra--;
184|         }
185|       } else {
186|         extra--;
187|       }
188|     }
189| 
190|     // place apples on open cells (not start)
191|     const openCells = [];
192|     for (let y = 0; y < GRID; y++)
193|       for (let x = 0; x < GRID; x++)
194|         if (grid[y][x] === 0 && !(x === 0 && y === 0)) openCells.push([x,y]);
195|     shuffle(openCells);
196|     const numApples = Math.min(5 + stage, openCells.length - 1);
197|     for (let i = 0; i < numApples; i++) {
198|       const [ax, ay] = openCells[i];
199|       grid[ay][ax] = 2;
200|     }
201|     // exit at far corner-ish, must be open
202|     let exitCell = [GRID-1, GRID-1];
203|     if (grid[exitCell[1]][exitCell[0]] === 1) grid[exitCell[1]][exitCell[0]] = 0;
204|     grid[exitCell[1]][exitCell[0]] = 3;
205| 
206|     applesTotal = numApples;
207|     hx = 0; hy = 0;
208|     stepsLeft = GRID * GRID + numApples * 2; // generous step budget
209|     score = 0;
210|   }
211| 
212|   function cellOpen(x, y) {
213|     if (!inBounds(x, y)) return false;
214|     return grid[y][x] !== 1;
215|   }
216| 
217|   function tryMove(dx, dy) {
218|     if (paused || gameOver || !started) return;
219|     const nx = hx + dx, ny = hy + dy;
220|     if (!cellOpen(nx, ny)) return;
221|     if (stepsLeft <= 0) return;
222|     hx = nx; hy = ny;
223|     stepsLeft -= 1;
224|     let scored = false;
225|     if (grid[hy][hx] === 2) {
226|       grid[hy][hx] = 0;
227|       score += 10;
228|       scored = true;
229|       CARTRIDGE.send('score', { value: score });
230|     }
231|     if (grid[hy][hx] === 3) {
232|       // reached exit
233|       gameOver = true;
234|       endReason = 'win';
235|       CARTRIDGE.send('end', { reason: 'win', value: score });
236|     } else if (stepsLeft <= 0) {
237|       // check if any legal move remains (there won't be steps to use anyway)
238|       gameOver = true;
239|       endReason = 'stuck';
240|       CARTRIDGE.send('end', { reason: 'stuck', value: score });
241|     }
242|     draw();
243|   }
244| 
245|   function anyMovesPossible() {
246|     return stepsLeft > 0;
247|   }
248| 
249|   // ---------- drawing ----------
250|   function drawShadowLayer(fn) {
251|     ctx.save();
252|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
253|     ctx.shadowBlur = 6;
254|     ctx.shadowOffsetY = 3;
255|     fn();
256|     ctx.restore();
257|   }
258| 
259|   function draw() {
260|     ctx.clearRect(0, 0, W, H);
261|     ctx.fillStyle = COLORS.bg;
262|     ctx.fillRect(0, 0, W, H);
263| 
264|     if (!started) {
265|       drawTitleScreen();
266|       return;
267|     }
268| 
269|     // board area
270|     const margin = 20;
271|     const topArea = 70;
272|     const boardSize = Math.min(W - margin * 2, H - topArea - 60);
273|     const cell = boardSize / GRID;
274|     const boardX = (W - boardSize) / 2;
275|     const boardY = topArea;
276| 
277|     // board backing card
278|     drawShadowLayer(() => {
279|       ctx.fillStyle = '#ffffff';
280|       roundRectPath(ctx, boardX - 10, boardY - 10, boardSize + 20, boardSize + 20, 14);
281|       ctx.fill();
282|     });
283| 
284|     // draw cells
285|     for (let y = 0; y < GRID; y++) {
286|       for (let x = 0; x < GRID; x++) {
287|         const cx = boardX + x * cell;
288|         const cy = boardY + y * cell;
289|         const val = grid[y][x];
290|         const key = 'cell'+x+'_'+y;
291| 
292|         if (val === 1) {
293|           // hedge - layer color polygon
294|           drawShadowLayer(() => {
295|             ctx.fillStyle = COLORS.layer;
296|             const pts = [
297|               [cx+3, cy+3],[cx+cell-3, cy+3],
298|               [cx+cell-3, cy+cell-3],[cx+3, cy+cell-3]
299|             ];
300|             jitteredPolygon(ctx, pts, key, 2);
301|             ctx.fill();
302|           });
303|           // texture dots
304|           ctx.fillStyle = COLORS.accent;
305|           ctx.globalAlpha = 0.25;
306|           for (let i = 0; i < 3; i++) {
307|             const dx = jitter(key+'dotx'+i, cell*0.3);
308|             const dy = jitter(key+'doty'+i, cell*0.3);
309|             ctx.beginPath();
310|             ctx.arc(cx+cell/2+dx, cy+cell/2+dy, cell*0.06, 0, Math.PI*2);
311|             ctx.fill();
312|           }
313|           ctx.globalAlpha = 1;
314|         } else {
315|           // open path, light card
316|           ctx.fillStyle = '#f9f4e8';
317|           roundRectPath(ctx, cx+2, cy+2, cell-4, cell-4, 4);
318|           ctx.fill();
319| 
320|           if (val === 2) {
321|             // apple - highlight circle
322|             drawShadowLayer(() => {
323|               ctx.fillStyle = '#c1443a';
324|               ctx.beginPath();
325|               ctx.arc(cx+cell/2, cy+cell/2, cell*0.22, 0, Math.PI*2);
326|               ctx.fill();
327|             });
328|             ctx.fillStyle = COLORS.highlight;
329|             ctx.beginPath();
330|             ctx.ellipse(cx+cell/2+cell*0.08, cy+cell/2-cell*0.2, cell*0.08, cell*0.05, 0.6, 0, Math.PI*2);
331|             ctx.fill();
332|           } else if (val === 3) {
333|             // exit - accent rounded square with arrow
334|             drawShadowLayer(() => {
335|               ctx.fillStyle = COLORS.highlight;
336|               roundRectPath(ctx, cx+6, cy+6, cell-12, cell-12, 6);
337|               ctx.fill();
338|             });
339|             ctx.fillStyle = COLORS.accent;
340|             ctx.font = `bold ${Math.floor(cell*0.4)}px sans-serif`;
341|             ctx.textAlign = 'center';
342|             ctx.textBaseline = 'middle';
343|             ctx.fillText('🏁', cx+cell/2, cy+cell/2+1);
344|           }
345|         }
346|       }
347|     }
348| 
349|     // hedgehog
350|     const hcx = boardX + hx * cell + cell/2;
351|     const hcy = boardY + hy * cell + cell/2;
352|     drawHedgehog(hcx, hcy, cell*0.38);
353| 
354|     // HUD
355|     drawHUD(boardY);
356| 
357|     if (gameOver) {
358|       drawEndOverlay();
359|     }
360|   }
361| 
362|   function drawHedgehog(cx, cy, r) {
363|     drawShadowLayer(() => {
364|       ctx.fillStyle = COLORS.accent;
365|       const pts = [
366|         [cx - r, cy + r*0.3],
367|         [cx - r*0.4, cy - r],
368|         [cx + r*0.3, cy - r*0.9],
369|         [cx + r, cy],
370|         [cx + r*0.5, cy + r*0.8],
371|         [cx - r*0.5, cy + r*0.9]
372|       ];
373|       jitteredPolygon(ctx, pts, 'hog', 1.5);
374|       ctx.fill();
375|     });
376|     // body
377|     ctx.fillStyle = '#caa26a';
378|     ctx.beginPath();
379|     ctx.ellipse(cx + r*0.1, cy + r*0.1, r*0.7, r*0.55, 0, 0, Math.PI*2);
380|     ctx.fill();
381|     // eye
382|     ctx.fillStyle = COLORS.accent;
383|     ctx.beginPath();
384|     ctx.arc(cx + r*0.55, cy - r*0.05, r*0.09, 0, Math.PI*2);
385|     ctx.fill();
386|     // nose
387|     ctx.beginPath();
388|     ctx.arc(cx + r*0.95, cy + r*0.05, r*0.08, 0, Math.PI*2);
389|     ctx.fill();
390|   }
391| 
392|   function drawHUD(boardTop) {
393|     // score card
394|     drawShadowLayer(() => {
395|       ctx.fillStyle = '#ffffff';
396|       roundRectPath(ctx, 16, 12, 150, 42, 10);
397|       ctx.fill();
398|     });
399|     ctx.fillStyle = COLORS.accent;
400|     ctx.font = 'bold 18px sans-serif';
401|     ctx.textAlign = 'left';
402|     ctx.textBaseline = 'middle';
403|     ctx.fillText('🍎 ' + score, 30, 33);
404| 
405|     // steps card
406|     drawShadowLayer(() => {
407|       ctx.fillStyle = '#ffffff';
408|       roundRectPath(ctx, W-166, 12, 150, 42, 10);
409|       ctx.fill();
410|     });
411|     ctx.fillStyle = COLORS.accent;
412|     ctx.textAlign = 'right';
413|     ctx.fillText('Pas: ' + Math.max(0,stepsLeft), W-30, 33);
414|   }
415| 
416|   function drawEndOverlay() {
417|     ctx.fillStyle = 'rgba(61,64,91,0.55)';
418|     ctx.fillRect(0, 0, W, H);
419| 
420|     drawShadowLayer(() => {
421|       ctx.fillStyle = '#ffffff';
422|       roundRectPath(ctx, W/2-160, H/2-90, 320, 180, 16);
423|       ctx.fill();
424|     });
425| 
426|     ctx.fillStyle = COLORS.accent;
427|     ctx.textAlign = 'center';
428|     ctx.textBaseline = 'middle';
429|     ctx.font = 'bold 26px sans-serif';
430|     const msg = endReason === 'win' ? 'Sortie atteinte !' : 'Plus de pas...';
431|     ctx.fillText(msg, W/2, H/2 - 30);
432|     ctx.font = '18px sans-serif';
433|     ctx.fillText('Score: ' + score, W/2, H/2 + 6);
434|     ctx.font = '15px sans-serif';
435|     ctx.fillText('Touchez pour recommencer', W/2, H/2 + 40);
436|   }
437| 
438|   function drawTitleScreen() {
439|     drawShadowLayer(() => {
440|       ctx.fillStyle = '#ffffff';
441|       roundRectPath(ctx, W/2-170, H/2-110, 340, 220, 18);
442|       ctx.fill();
443|     });
444|     ctx.fillStyle = COLORS.accent;
445|     ctx.textAlign = 'center';
446|     ctx.textBaseline = 'middle';
447|     ctx.font = 'bold 26px sans-serif';
448|     ctx.fillText('Le Hérisson des Haies', W/2, H/2 - 60);
449|     ctx.font = '16px sans-serif';
450|     wrapText('Glissez pour guider le hérisson à travers les haies et ramasser des pommes.', W/2, H/2 - 15, 300, 22);
451|     ctx.font = 'bold 18px sans-serif';
452|     ctx.fillStyle = COLORS.highlight;
453|     roundRectPath(ctx, W/2-90, H/2+50, 180, 46, 12);
454|     ctx.fill();
455|     ctx.fillStyle = COLORS.accent;
456|     ctx.fillText('Jouer', W/2, H/2+73);
457|   }
458| 
459|   function wrapText(text, x, y, maxWidth, lineHeight) {
460|     const words = text.split(' ');
461|     let line = '';
462|     let lines = [];
463|     for (let n = 0; n < words.length; n++) {
464|       const testLine = line + words[n] + ' ';
465|       const metrics = ctx.measureText(testLine);
466|       if (metrics.width > maxWidth && n > 0) {
467|         lines.push(line);
468|         line = words[n] + ' ';
469|       } else {
470|         line = testLine;
471|       }
472|     }
473|     lines.push(line);
474|     const startY = y - (lines.length - 1) * lineHeight / 2;
475|     lines.forEach((l, i) => ctx.fillText(l.trim(), x, startY + i * lineHeight));
476|   }
477| 
478|   // ---------- input ----------
479|   const SWIPE_FRACTION = 0.08;
480|   let pressX = 0, pressY = 0;
481| 
482|   canvas.addEventListener('pointerdown', (event) => {
483|     pressX = event.clientX;
484|     pressY = event.clientY;
485| 
486|     if (!started) {
487|       started = true;
488|       CARTRIDGE.send('start');
489|       CARTRIDGE.send('level', { index: stage });
490|       genMaze(Date.now() % 100000);
491|       draw();
492|       return;
493|     }
494|     if (gameOver) {
495|       resetGame();
496|       return;
497|     }
498|   });
499| 
500|   canvas.addEventListener('pointerup', (event) => {
501|     if (!started || gameOver || paused) return;
502|     const dx = event.clientX - pressX;
503|     const dy = event.clientY - pressY;
504|     const minSwipe = canvas.clientWidth * SWIPE_FRACTION;
505|     if (Math.abs(dx) < minSwipe && Math.abs(dy) < minSwipe) return;
506|     if (Math.abs(dx) > Math.abs(dy)) {
507|       tryMove(Math.sign(dx), 0);
508|     } else {
509|       tryMove(0, Math.sign(dy));
510|     }
511|   });
512| 
513|   window.addEventListener('keydown', (event) => {
514|     if (!started) {
515|       if (event.key === 'Enter' || event.key === ' ') {
516|         started = true;
517|         CARTRIDGE.send('start');
518|         CARTRIDGE.send('level', { index: stage });
519|         genMaze(Date.now() % 100000);
520|         draw();
521|       }
522|       return;
523|     }
524|     if (gameOver) {
525|       if (event.key === 'Enter' || event.key === ' ') resetGame();
526|       return;
527|     }
528|     if (paused) return;
529|     if (event.key === 'ArrowLeft') tryMove(-1, 0);
530|     else if (event.key === 'ArrowRight') tryMove(1, 0);
531|     else if (event.key === 'ArrowUp') tryMove(0, -1);
532|     else if (event.key === 'ArrowDown') tryMove(0, 1);
533|   });
534| 
535|   function resetGame() {
536|     stage += 1;
537|     gameOver = false;
538|     endReason = null;
539|     CARTRIDGE.send('level', { index: stage });
540|     genMaze(Date.now() % 100000 + stage * 777);
541|     draw();
542|   }
543| 
544|   function backToTitle() {
545|     started = false;
546|     gameOver = false;
547|     endReason = null;
548|     stage = 1;
549|     score = 0;
550|     paused = false;
551|     draw();
552|   }
553| 
554|   // ---------- host bridge ----------
555|   window.addEventListener("message", (event) => {
556|     const data = event.data;
557|     if (!data || data.source !== "cartridge-host") return;
558|     if (data.type === "pause") paused = true;
559|     if (data.type === "resume") paused = false;
560|     if (data.type === "reset") backToTitle();
561|   });
562| 
563|   // ---------- boot ----------
564|   resize();
565|   draw();
566|   CARTRIDGE.send("boot", { title: "Le Hérisson des Haies", gameType: "puzzle-board", lang: "fr" });
567| 
568|   // simple render loop to keep responsive to resize/pause without relying solely on events
569|   function loop() {
570|     requestAnimationFrame(loop);
571|   }
572|   loop();
573| })();
574| </script>
575| </body>
576| </html>
577|

